-- 525: Original BrillaPrep NSMQ subj_nsmq_chemistry speed_race beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_525_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_525_guard;
INSERT INTO _migration_525_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_sr_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_chem_atomic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the chemical symbol for the element sodium?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'Na' AND q.explanation IS 'Sodium’s symbol Na comes from its Latin name natrium. It is element 11, an alkali metal in group 1 whose atoms carry the electron configuration 2,8,1.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_sr_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_525_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_sr_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_chem_stoichiometry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How many particles are contained in one mole of any substance, to three significant figures?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS '6.02 × 10²³' AND q.explanation IS 'One mole contains the Avogadro constant of particles, NA = 6.02 × 10²³ mol⁻¹. The mole links laboratory masses to numbers of atoms, molecules or ions through n = N/NA.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_sr_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_525_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_sr_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_chem_organic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the molecular formula of methane?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'CH₄' AND q.explanation IS 'Methane is the simplest alkane, with one carbon atom bonded to four hydrogen atoms, giving CH₄. It fits the alkane general formula CₙH₂ₙ₊₂ with n = 1.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_sr_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_525_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_sr_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_chem_electrochemistry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which gas is liberated at the cathode during the electrolysis of dilute sulphuric acid?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'Hydrogen' AND q.explanation IS 'At the inert cathode, hydrogen ions are preferentially discharged and reduced: 2H⁺ + 2e⁻ → H₂. Oxygen is released at the anode from the oxidation of water or hydroxide species.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_sr_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_chem_sr_b002_001', 'topic_nsmq_chem_atomic', 'subj_nsmq_chemistry', 'exam_nsmq', NULL, NULL, 'What is the chemical symbol for the element sodium?', 'direct_answer', 'speed_race', NULL, 'Na', 'Sodium’s symbol Na comes from its Latin name natrium. It is element 11, an alkali metal in group 1 whose atoms carry the electron configuration 2,8,1.', 'easy', '2', '1', '15', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, NULL);
