INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_chem_sr_b002_003', 'topic_nsmq_chem_organic', 'subj_nsmq_chemistry', 'exam_nsmq', NULL, NULL, 'What is the molecular formula of methane?', 'direct_answer', 'speed_race', NULL, 'CH₄', 'Methane is the simplest alkane, with one carbon atom bonded to four hydrogen atoms, giving CH₄. It fits the alkane general formula CₙH₂ₙ₊₂ with n = 1.', 'easy', '2', '1', '15', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, NULL);
