INSERT INTO _migration_525_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_nsmq_chem_sr_b002_001', 'q_nsmq_chem_sr_b002_002', 'q_nsmq_chem_sr_b002_003', 'q_nsmq_chem_sr_b002_004')) = 4 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_nsmq_chem_sr_b002_001', 'q_nsmq_chem_sr_b002_002', 'q_nsmq_chem_sr_b002_003', 'q_nsmq_chem_sr_b002_004') AND r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 THEN 1 ELSE 0 END;
